<script setup lang="ts">import{reactive,ref}from"vue";import{open,save}from"@tauri-apps/plugin-dialog";import*as api from"../api";import AppDialog from"./AppDialog.vue";import{refresh,showToast,store}from"../store";const preview=ref<api.PackPreview|null>(null),path=ref(""),strategy=ref("skip"),busy=ref(false),showExport=ref(false);const meta=reactive({id:"local.my-recipes",name:"我的配方包",version:"1.0.0",description:"",author:"",homepage:"",license:"",tags:"",minimumAppVersion:"0.2.0"});async function chooseImport(){const p=await open({multiple:false,filters:[{name:"N1 Recipe Pack",extensions:["n1recipe.json","json"]}]});if(typeof p!=="string")return;try{path.value=p;preview.value=await api.previewRecipePack(p)}catch(e){showToast(e instanceof Error?e.message:String(e))}}async function doImport(){busy.value=true;try{const r=await api.importRecipePack(path.value,strategy.value);preview.value=null;await refresh();showToast(`导入完成：新增 ${r.added}，更新 ${r.updated}，跳过 ${r.skipped}`)}finally{busy.value=false}}async function doExport(){const p=await save({defaultPath:"n1-recipes.n1recipe.json",filters:[{name:"N1 Recipe Pack",extensions:["n1recipe.json"]}]});if(!p)return;busy.value=true;try{const count=await api.exportRecipePack(p,{...meta,tags:meta.tags.split(/[,，]/).map(x=>x.trim()).filter(Boolean),exportedAt:new Date().toISOString()},store.view==="category"?store.category:null,[]);showExport.value=false;showToast(`已导出 ${count} 条配方：${p}`)}finally{busy.value=false}}</script>
<template><div class="pack-actions"><button @click="showExport=true">导出配方包</button><button @click="chooseImport">导入配方包</button></div><p class="hint">分享前请检查 Token、密码、Cookie、私钥和个人路径；应用不会修改或执行配方内容。</p><AppDialog v-if="showExport" title="导出 N1 配方包" confirm-text="选择位置并导出" :busy="busy" @cancel="showExport=false" @confirm="doExport"><div class="fields"><label>Package ID<input v-model="meta.id"/></label><label>名称<input v-model="meta.name"/></label><label>版本<input v-model="meta.version"/></label><label>作者<input v-model="meta.author"/></label><label>说明<textarea v-model="meta.description"/></label><label>主页<input v-model="meta.homepage"/></label><label>许可证<input v-model="meta.license"/></label><label>标签<input v-model="meta.tags" placeholder="逗号分隔"/></label></div></AppDialog><AppDialog v-if="preview" title="导入配方包预览" confirm-text="确认导入" :busy="busy" @cancel="preview=null" @confirm="doImport"><div class="summary"><b>{{preview.package.name}}</b><p>{{preview.package.author}} · {{preview.package.version}}</p><p>{{preview.package.description}}</p><p>分类 {{preview.categoryCount}} · 配方 {{preview.recipeCount}} · 普通文本 {{preview.textCount}} · 命令组 {{preview.commandGroupCount}}</p><p>类型：{{preview.types.join('、')||'无'}}</p><p>标签：{{preview.tags.join('、')||'无'}}</p><p>检测到同来源冲突：{{preview.conflicts}}</p><p>主页：{{preview.package.homepage||'无'}}</p><label>冲突策略<select v-model="strategy"><option value="skip">跳过已有（默认）</option><option value="duplicate">保留两份</option><option value="overwrite">覆盖同来源配方</option></select></label></div></AppDialog></template>
<style scoped>.pack-actions{display:flex;gap:8px}.pack-actions button{padding:7px 12px;border:1px solid var(--border);border-radius:7px;background:var(--surface);color:var(--text)}.hint{color:var(--text-dim);font-size:var(--font-size-small)}.fields{display:grid;gap:10px}.fields label,.summary label{display:grid;gap:4px;color:var(--text-dim)}input,textarea,select{width:100%;padding:8px;border:1px solid var(--border);border-radius:7px;background:var(--surface);color:var(--text)}textarea{min-height:80px}.summary p{overflow-wrap:anywhere}</style>
